import{_ as n,c as a,o as r,a2 as o}from"./chunks/framework.B7el9cAC.js";const p=JSON.parse('{"title":"Mục 2.8 – Ôn Tập Chương 2: Mạng Máy Tính & Internet","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-2/2.8-on-tap.md","filePath":"chuong-2/2.8-on-tap.md","lastUpdated":1775298974000}'),h={name:"chuong-2/2.8-on-tap.md"};function s(d,t,i,g,e,c){return r(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="muc-2-8-–-on-tap-chuong-2-mang-may-tinh-internet" tabindex="-1">Mục 2.8 – Ôn Tập Chương 2: Mạng Máy Tính &amp; Internet <a class="header-anchor" href="#muc-2-8-–-on-tap-chuong-2-mang-may-tinh-internet" aria-label="Permalink to &quot;Mục 2.8 – Ôn Tập Chương 2: Mạng Máy Tính &amp; Internet&quot;">​</a></h1><blockquote><p><strong>Chương 2: Mạng máy tính và Internet</strong></p></blockquote><hr><h2 id="🔹-1-tom-tat-toan-bo-chuong-2" tabindex="-1">🔹 1. TÓM TẮT TOÀN BỘ CHƯƠNG 2 <a class="header-anchor" href="#🔹-1-tom-tat-toan-bo-chuong-2" aria-label="Permalink to &quot;🔹 1. TÓM TẮT TOÀN BỘ CHƯƠNG 2&quot;">​</a></h2><h3 id="so-đo-tong-quan-chuong-2" tabindex="-1">Sơ đồ tổng quan Chương 2 <a class="header-anchor" href="#so-đo-tong-quan-chuong-2" aria-label="Permalink to &quot;Sơ đồ tổng quan Chương 2&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CHƯƠNG 2: MẠNG MÁY TÍNH &amp; INTERNET</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 2.1 THIẾT BỊ MẠNG</span></span>
<span class="line"><span>│     ├── Switch (Tầng 2, dùng MAC)</span></span>
<span class="line"><span>│     ├── Router (Tầng 3, dùng IP)</span></span>
<span class="line"><span>│     ├── Modem (chuyển đổi tín hiệu)</span></span>
<span class="line"><span>│     ├── Access Point (phát Wi-Fi)</span></span>
<span class="line"><span>│     ├── Địa chỉ MAC (48 bit, vật lý, cố định)</span></span>
<span class="line"><span>│     └── Địa chỉ IP (32 bit IPv4, logic, thay đổi)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 2.2 TCP/IP</span></span>
<span class="line"><span>│     ├── TCP (Tầng 4, tin cậy, có ACK, 3-way handshake)</span></span>
<span class="line"><span>│     ├── UDP (Tầng 4, nhanh, không ACK)</span></span>
<span class="line"><span>│     └── IPv4 (32 bit, 4 octet, private: 192.168.x.x)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 2.3 LAN &amp; CHIA SẺ TÀI NGUYÊN</span></span>
<span class="line"><span>│     ├── Chia sẻ máy in, thư mục, ổ cứng</span></span>
<span class="line"><span>│     └── Phân quyền: Read, Write, Full Control</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 2.4 MÔ HÌNH OSI (7 tầng)</span></span>
<span class="line"><span>│     ├── 7-Application (HTTP, FTP, SMTP, DNS)</span></span>
<span class="line"><span>│     ├── 6-Presentation (SSL/TLS, mã hóa, nén)</span></span>
<span class="line"><span>│     ├── 5-Session (quản lý phiên)</span></span>
<span class="line"><span>│     ├── 4-Transport (TCP/UDP, Segment)</span></span>
<span class="line"><span>│     ├── 3-Network (IP, Router, Packet)</span></span>
<span class="line"><span>│     ├── 2-Data Link (MAC, Switch, Frame)</span></span>
<span class="line"><span>│     └── 1-Physical (Bit, cáp, sóng)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 2.5 INTERNET &amp; DỊCH VỤ</span></span>
<span class="line"><span>│     ├── WWW (HTTP/HTTPS, URL, domain name)</span></span>
<span class="line"><span>│     ├── Email (SMTP gửi, POP3/IMAP nhận)</span></span>
<span class="line"><span>│     ├── FTP (truyền file)</span></span>
<span class="line"><span>│     └── DNS (dịch tên miền → IP)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 2.6 BẢO MẬT MẠNG</span></span>
<span class="line"><span>│     ├── Malware: Virus, Worm, Trojan, Ransomware</span></span>
<span class="line"><span>│     ├── Phishing, DDoS, MITM</span></span>
<span class="line"><span>│     ├── Biện pháp: Firewall, Antivirus, Mã hóa, 2FA</span></span>
<span class="line"><span>│     └── Mật khẩu mạnh: dài 12+, phức tạp</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── 2.7 PHÂN LOẠI MẠNG</span></span>
<span class="line"><span>      ├── PAN (&lt; 10m, Bluetooth)</span></span>
<span class="line"><span>      ├── LAN (tòa nhà, Ethernet/Wi-Fi)</span></span>
<span class="line"><span>      ├── MAN (thành phố, cáp quang đô thị)</span></span>
<span class="line"><span>      ├── WAN (toàn cầu, Internet)</span></span>
<span class="line"><span>      ├── Topology: Star (phổ biến), Bus, Ring, Mesh</span></span>
<span class="line"><span>      └── Kiến trúc: Client-Server, P2P</span></span></code></pre></div><hr><h2 id="🔹-2-bang-tom-tat-nhanh-–-cac-khai-niem-cot-loi" tabindex="-1">🔹 2. BẢNG TÓM TẮT NHANH – CÁC KHÁI NIỆM CỐT LÕI <a class="header-anchor" href="#🔹-2-bang-tom-tat-nhanh-–-cac-khai-niem-cot-loi" aria-label="Permalink to &quot;🔹 2. BẢNG TÓM TẮT NHANH – CÁC KHÁI NIỆM CỐT LÕI&quot;">​</a></h2><h3 id="thiet-bi-mang" tabindex="-1">Thiết bị mạng <a class="header-anchor" href="#thiet-bi-mang" aria-label="Permalink to &quot;Thiết bị mạng&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Thiết bị</th><th>Chức năng</th><th>Tầng OSI</th><th>Địa chỉ dùng</th></tr></thead><tbody><tr><td>Hub</td><td>Khuếch đại tín hiệu, phát tán</td><td>Tầng 1</td><td>Không</td></tr><tr><td>Switch</td><td>Kết nối trong LAN, chuyển frame đúng cổng</td><td>Tầng 2</td><td>MAC</td></tr><tr><td>Router</td><td>Kết nối mạng, định tuyến</td><td>Tầng 3</td><td>IP</td></tr><tr><td>Modem</td><td>Chuyển đổi tín hiệu số ↔ analog/quang</td><td>Tầng 1</td><td>Không</td></tr><tr><td>Access Point</td><td>Phát sóng Wi-Fi</td><td>Tầng 2</td><td>MAC</td></tr></tbody></table><h3 id="giao-thuc-mang" tabindex="-1">Giao thức mạng <a class="header-anchor" href="#giao-thuc-mang" aria-label="Permalink to &quot;Giao thức mạng&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Giao thức</th><th>Tầng OSI</th><th>Chức năng</th><th>Cổng</th></tr></thead><tbody><tr><td>HTTP</td><td>7</td><td>Truyền tải trang web</td><td>80</td></tr><tr><td>HTTPS</td><td>7</td><td>HTTP có mã hóa SSL/TLS</td><td>443</td></tr><tr><td>FTP</td><td>7</td><td>Truyền file</td><td>21</td></tr><tr><td>SMTP</td><td>7</td><td><strong>Gửi</strong> email</td><td>25/587</td></tr><tr><td>POP3</td><td>7</td><td><strong>Nhận</strong> email (tải về, xóa server)</td><td>110/995</td></tr><tr><td>IMAP</td><td>7</td><td><strong>Nhận</strong> email (đồng bộ)</td><td>143/993</td></tr><tr><td>DNS</td><td>7</td><td>Phân giải tên miền → IP</td><td>53</td></tr><tr><td>TCP</td><td>4</td><td>Truyền tin cậy, có ACK</td><td>–</td></tr><tr><td>UDP</td><td>4</td><td>Truyền nhanh, không ACK</td><td>–</td></tr><tr><td>IP</td><td>3</td><td>Định tuyến, địa chỉ hóa</td><td>–</td></tr></tbody></table><h3 id="_7-tang-osi-va-đon-vi-du-lieu" tabindex="-1">7 tầng OSI và đơn vị dữ liệu <a class="header-anchor" href="#_7-tang-osi-va-đon-vi-du-lieu" aria-label="Permalink to &quot;7 tầng OSI và đơn vị dữ liệu&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tầng</th><th>Tên</th><th>Đơn vị dữ liệu</th><th>Thiết bị/Giao thức</th></tr></thead><tbody><tr><td>7</td><td>Application</td><td>Data</td><td>HTTP, FTP, SMTP, DNS</td></tr><tr><td>6</td><td>Presentation</td><td>Data</td><td>SSL/TLS, ZIP, JPEG</td></tr><tr><td>5</td><td>Session</td><td>Data</td><td>NetBIOS, RPC</td></tr><tr><td>4</td><td>Transport</td><td>Segment / Datagram</td><td>TCP, UDP</td></tr><tr><td>3</td><td>Network</td><td>Packet</td><td>IP, Router</td></tr><tr><td>2</td><td>Data Link</td><td>Frame</td><td>MAC, Switch, Ethernet</td></tr><tr><td>1</td><td>Physical</td><td>Bit</td><td>Cáp, Hub, Wi-Fi</td></tr></tbody></table><h3 id="phan-loai-mang" tabindex="-1">Phân loại mạng <a class="header-anchor" href="#phan-loai-mang" aria-label="Permalink to &quot;Phân loại mạng&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Loại</th><th>Phạm vi</th><th>Công nghệ</th><th>Ví dụ</th></tr></thead><tbody><tr><td>PAN</td><td>&lt; 10m</td><td>Bluetooth, USB</td><td>Tai nghe, smartwatch</td></tr><tr><td>LAN</td><td>Tòa nhà</td><td>Ethernet, Wi-Fi</td><td>Phòng máy, văn phòng</td></tr><tr><td>MAN</td><td>Thành phố</td><td>Cáp quang</td><td>Mạng đô thị</td></tr><tr><td>WAN</td><td>Toàn cầu</td><td>Cáp biển, vệ tinh</td><td>Internet</td></tr></tbody></table><hr><h2 id="🔹-3-đe-luyen-so-1-–-trac-nghiem-co-ban" tabindex="-1">🔹 3. ĐỀ LUYỆN SỐ 1 – TRẮC NGHIỆM CƠ BẢN <a class="header-anchor" href="#🔹-3-đe-luyen-so-1-–-trac-nghiem-co-ban" aria-label="Permalink to &quot;🔹 3. ĐỀ LUYỆN SỐ 1 – TRẮC NGHIỆM CƠ BẢN&quot;">​</a></h2><h3 id="cau-1" tabindex="-1">Câu 1: <a class="header-anchor" href="#cau-1" aria-label="Permalink to &quot;Câu 1:&quot;">​</a></h3><blockquote><p>Thiết bị nào dùng địa chỉ MAC để chuyển dữ liệu đến đúng thiết bị trong mạng nội bộ? A. Router B. Switch C. Modem D. Access Point</p></blockquote><p><strong>Đáp án: B – Switch</strong></p><hr><h3 id="cau-2" tabindex="-1">Câu 2: <a class="header-anchor" href="#cau-2" aria-label="Permalink to &quot;Câu 2:&quot;">​</a></h3><blockquote><p>Giao thức TCP khác UDP ở điểm nào sau đây? A. TCP dùng địa chỉ IP, UDP dùng địa chỉ MAC B. TCP hoạt động ở Tầng 3, UDP ở Tầng 4 C. TCP có cơ chế xác nhận (ACK) và gửi lại khi mất gói, UDP thì không D. TCP nhanh hơn UDP</p></blockquote><p><strong>Đáp án: C</strong></p><hr><h3 id="cau-3" tabindex="-1">Câu 3: <a class="header-anchor" href="#cau-3" aria-label="Permalink to &quot;Câu 3:&quot;">​</a></h3><blockquote><p>Địa chỉ IP <code>192.168.0.1</code> thuộc loại nào? A. Public IP B. Private IP C. IPv6 D. MAC Address</p></blockquote><p><strong>Đáp án: B – Private IP</strong></p><blockquote><p>Ba dải địa chỉ riêng tư theo RFC 1918: <code>10.0.0.0/8</code>, <code>172.16.0.0/12</code>, và <code>192.168.0.0/16</code>. Địa chỉ <code>192.168.0.1</code> thuộc dải thứ ba.</p></blockquote><hr><h3 id="cau-4" tabindex="-1">Câu 4: <a class="header-anchor" href="#cau-4" aria-label="Permalink to &quot;Câu 4:&quot;">​</a></h3><blockquote><p>Tầng nào của mô hình OSI chịu trách nhiệm định tuyến gói tin giữa các mạng khác nhau? A. Tầng 2 (Data Link) B. Tầng 3 (Network) C. Tầng 4 (Transport) D. Tầng 7 (Application)</p></blockquote><p><strong>Đáp án: B – Tầng 3 (Network)</strong></p><hr><h3 id="cau-5" tabindex="-1">Câu 5: <a class="header-anchor" href="#cau-5" aria-label="Permalink to &quot;Câu 5:&quot;">​</a></h3><blockquote><p>Giao thức nào dùng để <strong>gửi</strong> email? A. IMAP B. POP3 C. SMTP D. FTP</p></blockquote><p><strong>Đáp án: C – SMTP</strong></p><hr><h3 id="cau-6" tabindex="-1">Câu 6: <a class="header-anchor" href="#cau-6" aria-label="Permalink to &quot;Câu 6:&quot;">​</a></h3><blockquote><p>Loại malware nào <strong>tự lan sang máy tính khác qua mạng</strong> mà không cần người dùng thực hiện bất kỳ hành động nào? A. Virus B. Trojan C. Worm D. Ransomware</p></blockquote><p><strong>Đáp án: C – Worm</strong></p><hr><h3 id="cau-7" tabindex="-1">Câu 7: <a class="header-anchor" href="#cau-7" aria-label="Permalink to &quot;Câu 7:&quot;">​</a></h3><blockquote><p>Mạng nào có phạm vi địa lý lớn nhất? A. LAN B. PAN C. MAN D. WAN</p></blockquote><p><strong>Đáp án: D – WAN</strong></p><hr><h3 id="cau-8" tabindex="-1">Câu 8: <a class="header-anchor" href="#cau-8" aria-label="Permalink to &quot;Câu 8:&quot;">​</a></h3><blockquote><p>Topology nào phổ biến nhất trong mạng LAN văn phòng hiện đại? A. Bus B. Ring C. Star D. Mesh</p></blockquote><p><strong>Đáp án: C – Star</strong></p><hr><h3 id="cau-9" tabindex="-1">Câu 9: <a class="header-anchor" href="#cau-9" aria-label="Permalink to &quot;Câu 9:&quot;">​</a></h3><blockquote><p>HTTPS khác HTTP ở điểm chính nào? A. HTTPS dùng cổng 80, HTTP dùng cổng 443 B. HTTPS mã hóa dữ liệu bằng SSL/TLS, HTTP không mã hóa C. HTTPS chỉ dùng cho trang web ngân hàng D. HTTPS nhanh hơn HTTP</p></blockquote><p><strong>Đáp án: B</strong></p><hr><h3 id="cau-10" tabindex="-1">Câu 10: <a class="header-anchor" href="#cau-10" aria-label="Permalink to &quot;Câu 10:&quot;">​</a></h3><blockquote><p>Chức năng của DNS là gì? A. Mã hóa dữ liệu truyền qua Internet B. Dịch địa chỉ IP sang địa chỉ MAC C. Dịch tên miền (domain name) sang địa chỉ IP D. Phân phối địa chỉ IP tự động cho thiết bị</p></blockquote><p><strong>Đáp án: C</strong></p><hr><h2 id="🔹-4-đe-luyen-so-2-–-phan-tich-tinh-huong" tabindex="-1">🔹 4. ĐỀ LUYỆN SỐ 2 – PHÂN TÍCH TÌNH HUỐNG <a class="header-anchor" href="#🔹-4-đe-luyen-so-2-–-phan-tich-tinh-huong" aria-label="Permalink to &quot;🔹 4. ĐỀ LUYỆN SỐ 2 – PHÂN TÍCH TÌNH HUỐNG&quot;">​</a></h2><h3 id="cau-1-phan-tich-loi-mang" tabindex="-1">Câu 1: Phân tích lỗi mạng <a class="header-anchor" href="#cau-1-phan-tich-loi-mang" aria-label="Permalink to &quot;Câu 1: Phân tích lỗi mạng&quot;">​</a></h3><blockquote><p>Một học sinh báo: &quot;Em không vào được Internet nhưng vẫn in được tài liệu qua máy in mạng trong trường.&quot; Xác định: a) Tầng OSI nào có khả năng bị lỗi? b) Nguyên nhân có thể là gì?</p></blockquote><p><strong>Đáp án:</strong></p><p><strong>a) Tầng có khả năng bị lỗi:</strong> Tầng 3 (Network) trở lên.</p><p><strong>Lý do:</strong> In qua mạng nội bộ vẫn được → Tầng 1 (Physical), Tầng 2 (Data Link) và kết nối LAN nội bộ hoạt động bình thường. Lỗi xảy ra khi dữ liệu cần ra khỏi LAN (qua Router ra Internet) → vấn đề ở Tầng 3.</p><p><strong>b) Nguyên nhân có thể:</strong></p><ul><li>Default gateway (địa chỉ IP của Router) chưa được cấu hình đúng.</li><li>Router bị lỗi hoặc chưa kết nối với ISP.</li><li>IP của học sinh nằm ngoài dải IP được phép của trường.</li><li>Firewall của trường chặn kết nối Internet từ máy đó.</li></ul><hr><h3 id="cau-2-lua-chon-giao-thuc" tabindex="-1">Câu 2: Lựa chọn giao thức <a class="header-anchor" href="#cau-2-lua-chon-giao-thuc" aria-label="Permalink to &quot;Câu 2: Lựa chọn giao thức&quot;">​</a></h3><blockquote><p>Hãy chọn giao thức phù hợp cho từng tình huống và giải thích: a) Truyền trực tiếp kết quả thi đấu thể thao thời gian thực (live score) b) Gửi file hợp đồng PDF quan trọng qua Internet c) Tải website ngân hàng d) Chuyển file lớn lên server hosting</p></blockquote><p><strong>Đáp án:</strong></p><table tabindex="0"><thead><tr><th>Tình huống</th><th>Giao thức</th><th>Lý do</th></tr></thead><tbody><tr><td>a) Live score thời gian thực</td><td>UDP</td><td>Cần tốc độ, chấp nhận mất vài gói dữ liệu cũ</td></tr><tr><td>b) Gửi file PDF hợp đồng</td><td>TCP (qua email SMTP)</td><td>Phải đảm bảo file đến đủ, không mất byte</td></tr><tr><td>c) Tải website ngân hàng</td><td>HTTPS (TCP)</td><td>Cần mã hóa bảo mật + đảm bảo tải đủ trang</td></tr><tr><td>d) Chuyển file lên server</td><td>FTP/SFTP</td><td>Giao thức thiết kế cho truyền file</td></tr></tbody></table><hr><h3 id="cau-3-phan-tich-bao-mat" tabindex="-1">Câu 3: Phân tích bảo mật <a class="header-anchor" href="#cau-3-phan-tich-bao-mat" aria-label="Permalink to &quot;Câu 3: Phân tích bảo mật&quot;">​</a></h3><blockquote><p>Nhà trường nhận được nhiều email có chủ đề &quot;Kết quả thi của em đã có&quot; từ địa chỉ lạ, kèm file đính kèm. Một giáo viên đã mở file đính kèm và sau đó toàn bộ file bài giảng trên máy đó bị mã hóa, có thông báo đòi tiền chuộc. a) Đây là loại tấn công gì? b) Giải thích cơ chế tấn công. c) Nhà trường nên làm gì để khắc phục và phòng tránh trong tương lai?</p></blockquote><p><strong>Đáp án:</strong></p><p><strong>a) Loại tấn công:</strong> Phishing + Ransomware.</p><p><strong>b) Cơ chế:</strong></p><ul><li>Hacker gửi email <strong>phishing</strong> giả mạo, đính kèm file chứa <strong>Ransomware</strong> (có thể ẩn trong file .docx, .pdf, .exe giả mạo).</li><li>Giáo viên bị lừa mở file → Ransomware tự chạy trên máy.</li><li>Ransomware <strong>mã hóa tất cả file</strong> trên máy (và có thể cả thư mục mạng được share).</li><li>Hiển thị thông báo đòi tiền chuộc (thường bằng Bitcoin) để cung cấp khóa giải mã.</li></ul><p><strong>c) Khắc phục và phòng tránh:</strong></p><table tabindex="0"><thead><tr><th>Hành động</th><th>Mục đích</th></tr></thead><tbody><tr><td><strong>Ngắt kết nối mạng ngay</strong></td><td>Ngăn ransomware lây sang máy khác qua mạng</td></tr><tr><td><strong>Khôi phục từ bản backup</strong></td><td>Lấy lại dữ liệu (nếu đã backup trước)</td></tr><tr><td><strong>Quét toàn bộ hệ thống</strong> bằng antivirus</td><td>Loại bỏ ransomware</td></tr><tr><td><strong>Đào tạo nhận thức</strong> cho giáo viên về phishing</td><td>Phòng tránh tương lai</td></tr><tr><td><strong>Không mở file đính kèm</strong> từ email không rõ nguồn gốc</td><td>Phòng tránh</td></tr><tr><td><strong>Sao lưu định kỳ</strong> (backup 3-2-1)</td><td>Phục hồi khi bị tấn công lần sau</td></tr><tr><td><strong>Cài antivirus, cập nhật</strong> thường xuyên</td><td>Phát hiện malware mới</td></tr></tbody></table><hr><h3 id="cau-4-thiet-ke-mang" tabindex="-1">Câu 4: Thiết kế mạng <a class="header-anchor" href="#cau-4-thiet-ke-mang" aria-label="Permalink to &quot;Câu 4: Thiết kế mạng&quot;">​</a></h3><blockquote><p>Một công ty khởi nghiệp có 15 nhân viên làm việc trong 1 văn phòng, cần:</p><ul><li>15 máy tính kết nối có dây ổn định</li><li>20 thiết bị di động kết nối Wi-Fi (điện thoại, tablet)</li><li>Kết nối Internet băng thông 500 Mbps</li><li>Dữ liệu công ty được lưu tập trung, dễ backup</li></ul><p>Hãy thiết kế hệ thống mạng: liệt kê thiết bị, topology, và kiến trúc phù hợp.</p></blockquote><p><strong>Đáp án gợi ý:</strong></p><p><strong>Kiến trúc:</strong> Client – Server (có server lưu dữ liệu tập trung)</p><p><strong>Topology:</strong> Star (Switch là trung tâm)</p><p><strong>Thiết bị:</strong></p><table tabindex="0"><thead><tr><th>Thiết bị</th><th>SL</th><th>Vai trò</th></tr></thead><tbody><tr><td>Modem cáp quang</td><td>1</td><td>Kết nối đường truyền ISP 500 Mbps</td></tr><tr><td>Router</td><td>1</td><td>Định tuyến, NAT, DHCP, tường lửa</td></tr><tr><td>Switch 24 cổng</td><td>1</td><td>Kết nối 15 PC + server + Access Point</td></tr><tr><td>Access Point Wi-Fi</td><td>2</td><td>Phủ sóng cho 20 thiết bị di động (mỗi AP ~10 thiết bị để tránh nghẽn)</td></tr><tr><td>Server NAS</td><td>1</td><td>Lưu dữ liệu tập trung, dễ backup</td></tr><tr><td>Cáp Ethernet Cat6</td><td>15+</td><td>Kết nối PC và server đến Switch</td></tr></tbody></table><p><strong>Sơ đồ:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Internet 500Mbps]</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>   [Modem]</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>   [Router] ← DHCP, NAT, Firewall</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>  [Switch 24 cổng]</span></span>
<span class="line"><span>  /    |     |    \\</span></span>
<span class="line"><span>[PC×15] [AP1] [AP2] [Server NAS]</span></span>
<span class="line"><span>         |     |</span></span>
<span class="line"><span>    [Mobile×10] [Mobile×10]</span></span></code></pre></div><hr><h2 id="🔹-5-đe-luyen-so-3-–-cau-hoi-tong-hop" tabindex="-1">🔹 5. ĐỀ LUYỆN SỐ 3 – CÂU HỎI TỔNG HỢP <a class="header-anchor" href="#🔹-5-đe-luyen-so-3-–-cau-hoi-tong-hop" aria-label="Permalink to &quot;🔹 5. ĐỀ LUYỆN SỐ 3 – CÂU HỎI TỔNG HỢP&quot;">​</a></h2><h3 id="cau-1-đien-vao-bang-so-sanh" tabindex="-1">Câu 1: Điền vào bảng so sánh <a class="header-anchor" href="#cau-1-đien-vao-bang-so-sanh" aria-label="Permalink to &quot;Câu 1: Điền vào bảng so sánh&quot;">​</a></h3><blockquote><p>Hoàn thành bảng so sánh sau:</p></blockquote><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>TCP</th><th>UDP</th></tr></thead><tbody><tr><td>Kiểu kết nối</td><td>?</td><td>Phi kết nối</td></tr><tr><td>Xác nhận (ACK)</td><td>?</td><td>Không</td></tr><tr><td>Gửi lại khi mất</td><td>?</td><td>?</td></tr><tr><td>Tốc độ</td><td>Chậm hơn</td><td>?</td></tr><tr><td>Dùng cho</td><td>?</td><td>Game, video call, DNS</td></tr></tbody></table><p><strong>Đáp án:</strong></p><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>TCP</th><th>UDP</th></tr></thead><tbody><tr><td>Kiểu kết nối</td><td><strong>Hướng kết nối</strong> (connection-oriented)</td><td>Phi kết nối</td></tr><tr><td>Xác nhận (ACK)</td><td><strong>Có</strong></td><td>Không</td></tr><tr><td>Gửi lại khi mất</td><td><strong>Có</strong></td><td><strong>Không</strong></td></tr><tr><td>Tốc độ</td><td>Chậm hơn</td><td><strong>Nhanh hơn</strong></td></tr><tr><td>Dùng cho</td><td><strong>Web, email, tải file</strong></td><td>Game, video call, DNS</td></tr></tbody></table><hr><h3 id="cau-2-phan-tich-đia-chi-ip" tabindex="-1">Câu 2: Phân tích địa chỉ IP <a class="header-anchor" href="#cau-2-phan-tich-đia-chi-ip" aria-label="Permalink to &quot;Câu 2: Phân tích địa chỉ IP&quot;">​</a></h3><blockquote><p>Cho địa chỉ IP <code>10.0.5.200</code>: a) Đây là IP công cộng hay IP riêng tư? Vì sao? b) Thiết bị này có thể truy cập Internet trực tiếp không? Vì sao? c) Để ra Internet, cần cơ chế gì?</p></blockquote><p><strong>Đáp án:</strong></p><p><strong>a) IP riêng tư (Private IP)</strong> Dải <code>10.0.0.0 – 10.255.255.255</code> là một trong ba dải địa chỉ riêng tư theo RFC 1918, không được định tuyến trên Internet công cộng.</p><p><strong>b) Không thể truy cập Internet trực tiếp</strong> IP riêng tư không được định tuyến trên Internet – các Router trên Internet sẽ <strong>không biết</strong> cách chuyển gói tin về địa chỉ <code>10.0.5.200</code>.</p><p><strong>c) Cần NAT (Network Address Translation)</strong> Router sẽ dùng NAT để <strong>dịch địa chỉ IP riêng tư</strong> (<code>10.0.5.200</code>) sang <strong>IP công cộng</strong> (do ISP cấp) khi gói tin ra Internet. Khi gói tin trả về, Router dịch ngược lại IP công cộng → IP riêng tư và chuyển đến thiết bị đúng.</p><hr><h3 id="cau-3-mo-hinh-osi-trong-thuc-te" tabindex="-1">Câu 3: Mô hình OSI trong thực tế <a class="header-anchor" href="#cau-3-mo-hinh-osi-trong-thuc-te" aria-label="Permalink to &quot;Câu 3: Mô hình OSI trong thực tế&quot;">​</a></h3><blockquote><p>Khi bạn truy cập trang <code>https://moj.gov.vn</code> (Bộ Tư pháp Việt Nam), hãy xác định: a) Giao thức ở Tầng 7 là gì? b) Tầng 6 thực hiện chức năng gì? c) Cổng TCP mà kết nối sử dụng là bao nhiêu? d) Tên miền cấp cao (TLD) của website này là gì?</p></blockquote><p><strong>Đáp án:</strong></p><table tabindex="0"><thead><tr><th>Câu</th><th>Đáp án</th><th>Giải thích</th></tr></thead><tbody><tr><td>a) Giao thức Tầng 7</td><td><strong>HTTPS</strong></td><td>Website dùng HTTPS (HTTP Secure) để truyền tải</td></tr><tr><td>b) Tầng 6 làm gì</td><td><strong>Mã hóa SSL/TLS</strong></td><td>Tầng Presentation mã hóa dữ liệu bằng TLS để bảo mật</td></tr><tr><td>c) Cổng TCP</td><td><strong>443</strong></td><td>HTTPS mặc định dùng cổng 443</td></tr><tr><td>d) TLD</td><td><strong>.vn</strong></td><td><code>.gov.vn</code> → TLD quốc gia Việt Nam, cấp 2 <code>.gov</code> (chính phủ)</td></tr></tbody></table><hr><h3 id="cau-4-bao-mat-thuc-hanh" tabindex="-1">Câu 4: Bảo mật thực hành <a class="header-anchor" href="#cau-4-bao-mat-thuc-hanh" aria-label="Permalink to &quot;Câu 4: Bảo mật thực hành&quot;">​</a></h3><blockquote><p>Đánh giá bảo mật của các hành động sau và đề xuất cải thiện:</p><p>a) Học sinh dùng mật khẩu <code>hocsinh2024</code> cho tài khoản trường học. b) Giáo viên dùng Wi-Fi quán cà phê để nộp điểm thi qua trang HTTP của trường. c) Văn phòng không backup dữ liệu vì &quot;máy tính hiếm khi hỏng&quot;. d) Nhân viên dùng cùng một mật khẩu cho tài khoản email và tài khoản ngân hàng.</p></blockquote><p><strong>Đáp án:</strong></p><table tabindex="0"><thead><tr><th>Hành động</th><th>Vấn đề bảo mật</th><th>Cải thiện</th></tr></thead><tbody><tr><td>a) <code>hocsinh2024</code></td><td>❌ Mật khẩu yếu: chứa từ dễ đoán, thiếu ký tự đặc biệt</td><td>Dùng mật khẩu 12+ ký tự, hoa/thường/số/ký tự đặc biệt, ví dụ: <code>Tr@ng!X7k#2024</code></td></tr><tr><td>b) HTTP + Wi-Fi quán</td><td>❌❌ Hai lỗi: HTTP không mã hóa + Wi-Fi công cộng dễ bị nghe lén</td><td>Yêu cầu trường dùng HTTPS; giáo viên dùng 4G/5G riêng hoặc VPN</td></tr><tr><td>c) Không backup</td><td>❌ Mất dữ liệu nếu bị ransomware, cháy nổ, hỏng ổ cứng</td><td>Backup định kỳ hàng ngày theo quy tắc 3-2-1</td></tr><tr><td>d) Dùng chung mật khẩu</td><td>❌❌ Nếu 1 tài khoản bị lộ → tất cả bị lộ</td><td>Dùng mật khẩu <strong>khác nhau</strong> cho mỗi tài khoản; dùng Password Manager</td></tr></tbody></table><hr><h2 id="🔹-6-bang-ghi-nho-tong-hop-–-đi-thi" tabindex="-1">🔹 6. BẢNG GHI NHỚ TỔNG HỢP – ĐI THI <a class="header-anchor" href="#🔹-6-bang-ghi-nho-tong-hop-–-đi-thi" aria-label="Permalink to &quot;🔹 6. BẢNG GHI NHỚ TỔNG HỢP – ĐI THI&quot;">​</a></h2><h3 id="⚡-nhung-đieu-chac-chan-ra-thi" tabindex="-1">⚡ Những điều CHẮC CHẮN ra thi <a class="header-anchor" href="#⚡-nhung-đieu-chac-chan-ra-thi" aria-label="Permalink to &quot;⚡ Những điều CHẮC CHẮN ra thi&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Chủ đề</th><th>Điều cần nhớ</th></tr></thead><tbody><tr><td><strong>Switch</strong></td><td>Tầng 2, dùng địa chỉ <strong>MAC</strong>, kết nối trong <strong>LAN</strong></td></tr><tr><td><strong>Router</strong></td><td>Tầng 3, dùng địa chỉ <strong>IP</strong>, kết nối <strong>giữa các mạng</strong></td></tr><tr><td><strong>Modem</strong></td><td>Chuyển đổi tín hiệu <strong>số ↔ analog</strong>, kết nối với <strong>ISP</strong></td></tr><tr><td><strong>TCP</strong></td><td>Tin cậy, có <strong>ACK</strong>, <strong>3-way handshake</strong>, dùng cho web/email</td></tr><tr><td><strong>UDP</strong></td><td>Nhanh, <strong>không ACK</strong>, dùng cho game/video call</td></tr><tr><td><strong>IPv4</strong></td><td><strong>32 bit</strong>, dạng <code>X.X.X.X</code>, private: <code>192.168.x.x</code></td></tr><tr><td><strong>OSI Tầng 7</strong></td><td>Application: <strong>HTTP, HTTPS, FTP, SMTP, DNS</strong></td></tr><tr><td><strong>OSI Tầng 4</strong></td><td>Transport: <strong>TCP/UDP</strong>, đơn vị: <strong>Segment</strong></td></tr><tr><td><strong>OSI Tầng 3</strong></td><td>Network: <strong>IP</strong>, thiết bị: <strong>Router</strong>, đơn vị: <strong>Packet</strong></td></tr><tr><td><strong>OSI Tầng 2</strong></td><td>Data Link: <strong>MAC</strong>, thiết bị: <strong>Switch</strong>, đơn vị: <strong>Frame</strong></td></tr><tr><td><strong>OSI Tầng 1</strong></td><td>Physical: <strong>Bit</strong>, thiết bị: <strong>Hub, cáp</strong></td></tr><tr><td><strong>SMTP</strong></td><td><strong>Gửi</strong> email, cổng <strong>25/587</strong></td></tr><tr><td><strong>IMAP</strong></td><td><strong>Nhận</strong> email, <strong>đồng bộ nhiều thiết bị</strong>, cổng <strong>143/993</strong></td></tr><tr><td><strong>POP3</strong></td><td><strong>Nhận</strong> email, tải về <strong>xóa server</strong>, cổng <strong>110/995</strong></td></tr><tr><td><strong>FTP</strong></td><td><strong>Truyền file</strong>, cổng <strong>21</strong></td></tr><tr><td><strong>HTTPS</strong></td><td>HTTP + mã hóa <strong>SSL/TLS</strong>, cổng <strong>443</strong></td></tr><tr><td><strong>DNS</strong></td><td>Dịch <strong>tên miền → IP</strong>, cổng <strong>53</strong></td></tr><tr><td><strong>Worm</strong></td><td><strong>Tự lan qua mạng</strong>, không cần người dùng</td></tr><tr><td><strong>Virus</strong></td><td><strong>Gắn vào file</strong>, cần người dùng chạy</td></tr><tr><td><strong>Ransomware</strong></td><td><strong>Mã hóa dữ liệu</strong>, đòi tiền chuộc</td></tr><tr><td><strong>Phishing</strong></td><td><strong>Giả mạo</strong> tổ chức uy tín, lừa lấy thông tin</td></tr><tr><td><strong>Firewall</strong></td><td><strong>Kiểm soát luồng</strong> dữ liệu vào/ra theo quy tắc</td></tr><tr><td><strong>LAN</strong></td><td>Tòa nhà, <strong>Ethernet/Wi-Fi</strong>, tốc độ cao</td></tr><tr><td><strong>WAN</strong></td><td>Toàn cầu, <strong>Internet</strong></td></tr><tr><td><strong>Star topology</strong></td><td>Switch trung tâm, <strong>phổ biến nhất</strong> hiện nay</td></tr><tr><td><strong>Client-Server</strong></td><td>Server tập trung, <strong>quản lý dễ</strong>, bảo mật tốt</td></tr></tbody></table><h3 id="🔢-cac-con-so-can-nho" tabindex="-1">🔢 Các con số cần nhớ <a class="header-anchor" href="#🔢-cac-con-so-can-nho" aria-label="Permalink to &quot;🔢 Các con số cần nhớ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Con số</th><th>Ý nghĩa</th></tr></thead><tbody><tr><td><strong>7</strong></td><td>Số tầng của mô hình OSI</td></tr><tr><td><strong>4</strong></td><td>Số tầng của mô hình TCP/IP</td></tr><tr><td><strong>32</strong></td><td>Số bit địa chỉ IPv4</td></tr><tr><td><strong>128</strong></td><td>Số bit địa chỉ IPv6</td></tr><tr><td><strong>48</strong></td><td>Số bit địa chỉ MAC</td></tr><tr><td><strong>80</strong></td><td>Cổng HTTP</td></tr><tr><td><strong>443</strong></td><td>Cổng HTTPS</td></tr><tr><td><strong>25/587</strong></td><td>Cổng SMTP</td></tr><tr><td><strong>110/995</strong></td><td>Cổng POP3</td></tr><tr><td><strong>143/993</strong></td><td>Cổng IMAP</td></tr><tr><td><strong>21</strong></td><td>Cổng FTP</td></tr><tr><td><strong>53</strong></td><td>Cổng DNS</td></tr></tbody></table><hr><h2 id="🔹-7-cac-cau-hoi-thuong-gap-nhat-trong-đe-thi" tabindex="-1">🔹 7. CÁC CÂU HỎI THƯỜNG GẶP NHẤT TRONG ĐỀ THI <a class="header-anchor" href="#🔹-7-cac-cau-hoi-thuong-gap-nhat-trong-đe-thi" aria-label="Permalink to &quot;🔹 7. CÁC CÂU HỎI THƯỜNG GẶP NHẤT TRONG ĐỀ THI&quot;">​</a></h2><h3 id="❓-hoi-ve-thiet-bi-mang" tabindex="-1">❓ Hỏi về thiết bị mạng <a class="header-anchor" href="#❓-hoi-ve-thiet-bi-mang" aria-label="Permalink to &quot;❓ Hỏi về thiết bị mạng&quot;">​</a></h3><p><strong>Q: Switch dùng địa chỉ gì để chuyển dữ liệu?</strong> → <strong>MAC address</strong> (địa chỉ vật lý).</p><p><strong>Q: Router dùng địa chỉ gì để định tuyến?</strong> → <strong>IP address</strong> (địa chỉ logic).</p><p><strong>Q: Thiết bị nào kết nối mạng LAN với Internet?</strong> → <strong>Router</strong> (kết hợp với Modem).</p><hr><h3 id="❓-hoi-ve-tcp-ip-va-osi" tabindex="-1">❓ Hỏi về TCP/IP và OSI <a class="header-anchor" href="#❓-hoi-ve-tcp-ip-va-osi" aria-label="Permalink to &quot;❓ Hỏi về TCP/IP và OSI&quot;">​</a></h3><p><strong>Q: TCP khác UDP ở điểm gì quan trọng nhất?</strong> → TCP <strong>có ACK</strong> (xác nhận và gửi lại nếu mất), UDP <strong>không có ACK</strong>.</p><p><strong>Q: Giao thức nào dùng để truyền file mà không thể mất dữ liệu?</strong> → <strong>TCP</strong> (có cơ chế đảm bảo độ tin cậy).</p><p><strong>Q: Router hoạt động ở tầng mấy của OSI?</strong> → <strong>Tầng 3 (Network Layer)</strong>.</p><p><strong>Q: Switch hoạt động ở tầng mấy của OSI?</strong> → <strong>Tầng 2 (Data Link Layer)</strong>.</p><hr><h3 id="❓-hoi-ve-dich-vu-internet" tabindex="-1">❓ Hỏi về dịch vụ Internet <a class="header-anchor" href="#❓-hoi-ve-dich-vu-internet" aria-label="Permalink to &quot;❓ Hỏi về dịch vụ Internet&quot;">​</a></h3><p><strong>Q: SMTP, POP3, IMAP dùng để làm gì?</strong> → SMTP: <strong>gửi</strong> email. POP3 + IMAP: <strong>nhận</strong> email (POP3 tải về xóa server, IMAP đồng bộ nhiều thiết bị).</p><p><strong>Q: DNS làm nhiệm vụ gì?</strong> → <strong>Dịch tên miền</strong> (ví dụ <code>google.com</code>) <strong>sang địa chỉ IP</strong> (ví dụ <code>142.250.196.46</code>).</p><p><strong>Q: HTTPS khác HTTP ở điểm gì?</strong> → HTTPS <strong>mã hóa bằng SSL/TLS</strong>, HTTP không mã hóa; HTTPS dùng cổng <strong>443</strong>, HTTP dùng cổng <strong>80</strong>.</p><hr><h3 id="❓-hoi-ve-bao-mat" tabindex="-1">❓ Hỏi về bảo mật <a class="header-anchor" href="#❓-hoi-ve-bao-mat" aria-label="Permalink to &quot;❓ Hỏi về bảo mật&quot;">​</a></h3><p><strong>Q: Phần mềm nào tự lan qua mạng không cần người dùng?</strong> → <strong>Worm</strong> (khác với Virus cần gắn vào file và cần người dùng chạy).</p><p><strong>Q: Ransomware là gì?</strong> → Phần mềm <strong>mã hóa dữ liệu</strong> của nạn nhân và <strong>đòi tiền chuộc</strong> để giải mã.</p><p><strong>Q: Phishing là gì?</strong> → Kỹ thuật <strong>giả mạo</strong> tổ chức uy tín (ngân hàng, Google...) để <strong>lừa lấy thông tin</strong> (mật khẩu, số tài khoản...).</p><p><strong>Q: Firewall là gì?</strong> → Hệ thống <strong>kiểm soát luồng dữ liệu</strong> vào/ra mạng, cho phép hoặc <strong>chặn</strong> dựa trên quy tắc.</p><hr><h3 id="❓-hoi-ve-phan-loai-mang" tabindex="-1">❓ Hỏi về phân loại mạng <a class="header-anchor" href="#❓-hoi-ve-phan-loai-mang" aria-label="Permalink to &quot;❓ Hỏi về phân loại mạng&quot;">​</a></h3><p><strong>Q: Sắp xếp theo phạm vi từ nhỏ đến lớn: LAN, WAN, MAN, PAN?</strong> → <strong>PAN &lt; LAN &lt; MAN &lt; WAN</strong>.</p><p><strong>Q: Topology nào phổ biến nhất trong mạng LAN văn phòng?</strong> → <strong>Star (hình sao)</strong> – tất cả thiết bị kết nối vào Switch trung tâm.</p><p><strong>Q: Internet là loại mạng gì?</strong> → <strong>WAN</strong> (Wide Area Network) – mạng diện rộng toàn cầu.</p>`,149)])])}const u=n(h,[["render",s]]);export{p as __pageData,u as default};
